import { expect, expectStatus, test } from "../../fixtures";

test.describe("manage vendors", () => {
  test("a vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs }) => {
    // Arrange: a member creates a vendor and submits it, so it is in review.
    const member = await apiAs("member");
    const uniqueSuffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    const created = await member.post("/api/vendors", {
      data: {
        name: `VEN-09 Vendor ${uniqueSuffix}`,
        category: "logistics",
        contact_email: `contact-${uniqueSuffix}@northwind.example`,
      },
    });
    const vendor = await expectStatus(created, 201);

    const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
    const submittedVendor = await expectStatus(submitted, 200);
    expect(submittedVendor.status).toBe("in_review");

    // Act: attempt to change the contact email while the vendor is under review.
    const response = await member.patch(`/api/vendors/${vendor.id}`, {
      data: { contact_email: "billing@acmefreight.example" },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("vendor_locked");
  });
});
